D_sql_completion:
WITH RECURSIVE reach(company) AS (
    SELECT 'GSC Steel Stamping LLC'
    UNION
    SELECT b.src FROM reach a JOIN graph_edges b ON b.dst = a.src AND b.rel = 'SUPPLIES_OEM'
) SELECT DISTINCT src FROM graph_edges WHERE dst = ANY(SELECT company FROM reach) AND rel = 'SUPPLIES_OEM' AND src != 'GSC Steel Stamping LLC' ORDER BY src;

SELECT DISTINCT c FROM (
  SELECT src c FROM graph_edges WHERE dst = 'Hanon Systems USA LLC' AND rel = 'SUPPLIES_OEM'
  UNION ALL
  SELECT dst c FROM graph_edges WHERE src = 'Hanon Systems USA LLC' AND rel = 'SUPPLIES_OEM'
) t WHERE c != 'Hanon Systems USA LLC' ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT src c FROM graph_edges WHERE dst = 'Hitachi Astemo Americas Inc.' AND rel = 'SUPPLIES_OEM'
  UNION ALL
  SELECT dst c FROM graph_edges WHERE src = 'Hitachi Astemo Americas Inc.' AND rel = 'SUPPLIES_OEM'
) t WHERE c != 'Hitachi Astemo Americas Inc.' ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT src FROM graph_edges WHERE dst = 'Hollingsworth & Vose Co.' AND rel = 'SUPPLIES_OEM'
  UNION ALL
  SELECT dst FROM graph_edges WHERE src = 'Hollingsworth & Vose Co.' AND rel = 'SUPPLIES_OEM'
) a JOIN graph_edges b ON a.src = b.src AND b.rel = 'SUPPLIES_OEM' WHERE c <> 'Hollingsworth & Vose Co.' GROUP BY c ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT src c FROM graph_edges WHERE dst = 'Honda Development & Manufacturing' AND rel = 'SUPPLIES_OEM'
  UNION ALL
  SELECT dst c FROM graph_edges WHERE src = 'Honda Development & Manufacturing' AND rel = 'SUPPLIES_OEM'
) WHERE c != 'Honda Development & Manufacturing' ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT src c FROM graph_edges WHERE dst = 'Hyundai Motor Group' AND rel = 'SUPPLIES_OEM'
  UNION ALL
  SELECT dst c FROM graph_edges WHERE src = 'Hyundai Motor Group' AND rel = 'SUPPLIES_OEM'
) WHERE c != 'Hyundai Motor Group' ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT src c FROM graph_edges WHERE dst = 'IMMI' AND rel = 'SUPPLIES_OEM'
  UNION ALL
  SELECT dst c FROM graph_edges WHERE src = 'IMMI' AND rel = 'SUPPLIES_OEM'
) t WHERE c != 'IMMI' ORDER BY c;

WITH RECURSIVE reach(company) AS (
    SELECT 'Perkins Small Engines LLC'
    UNION
    SELECT b.src FROM reach a JOIN graph_edges b ON b.dst = a.src AND b.rel = 'SUPPLIES_OEM'
) SELECT DISTINCT c FROM (
    SELECT src c FROM graph_edges WHERE dst = 'Perkins Small Engines LLC' AND rel = 'SUPPLIES_OEM'
    UNION ALL
    SELECT company FROM reach
) WHERE c != 'Perkins Small Engines LLC' ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT src c FROM graph_edges WHERE src = 'Racemark International LLC' AND rel = 'SUPPLIES_OEM'
  UNION ALL
  SELECT dst c FROM graph_edges WHERE dst = 'Racemark International LLC' AND rel = 'SUPPLIES_OEM'
) t WHERE c != 'Racemark International LLC' ORDER BY c;

WITH RECURSIVE reach(company) AS (
    SELECT DISTINCT src FROM graph_edges WHERE dst = 'Superior Essex Inc.' AND rel = 'SUPPLIES_OEM'
    UNION
    SELECT DISTINCT src FROM graph_edges WHERE dst IN (SELECT company FROM reach) AND rel = 'SUPPLIES_OEM'
) SELECT DISTINCT company FROM reach WHERE company != 'Superior Essex Inc.' ORDER BY company;

SELECT DISTINCT c FROM (
  SELECT src c FROM graph_edges WHERE dst = 'Suzuki Manufacturing of America Corp.' AND rel = 'SUPPLIES_OEM'
  UNION ALL
  SELECT dst c FROM graph_edges WHERE src = 'Suzuki Manufacturing of America Corp.' AND rel = 'SUPPLIES_OEM'
) WHERE c != 'Suzuki Manufacturing of America Corp.' ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT src c FROM graph_edges WHERE rel = 'SUPPLIES_OEM' AND dst = 'TE Connectivity'
  UNION ALL
  SELECT dst c FROM graph_edges WHERE rel = 'SUPPLIES_OEM' AND src = 'TE Connectivity'
) t WHERE c != 'TE Connectivity' ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT dst AS c FROM graph_edges WHERE src = 'Lund International Inc./Ventshade Division' AND rel = 'HOLDS_STANDARD'
  UNION ALL
  SELECT src FROM graph_edges WHERE dst = 'Lund International Inc./Ventshade Division' AND rel = 'HOLDS_STANDARD'
) WHERE c != 'Lund International Inc./Ventshade Division' GROUP BY c ORDER BY c;

SELECT DISTINCT c FROM (
  SELECT DISTINCT company FROM certifications WHERE standard_family IN (
    SELECT standard_family FROM certifications WHERE company = 'Rivian Automotive'
  )
  AND company != 'Rivian Automotive'
  ORDER BY company
) c;

SELECT DISTINCT c.company FROM graph_edges k JOIN certifications m ON k.src = m.row_id
WHERE k.rel = 'SUPPLIES_OEM' AND k.dst = 'Club Car' AND m.standard_family = 'ISO/TS 16949'
ORDER BY c.company;

SELECT DISTINCT c.company FROM graph_edges k JOIN graph_edges i ON k.src = i.src
WHERE k.rel = 'SUPPLIES_OEM' AND k.dst = 'Kia' AND i.rel = 'HOLDS_STANDARD' AND i.dst = 'ISO/TS 16949'
ORDER BY c.company;

SELECT DISTINCT c.company FROM graph_edges k JOIN graph_edges q ON k.src = q.src
WHERE k.rel = 'SUPPLIES_OEM' AND k.dst = 'Kia' AND q.rel = 'HOLDS_STANDARD' AND q.dst = 'QUALICOAT'
ORDER BY c.company;

SELECT DISTINCT c.company FROM graph_edges k JOIN graph_edges u ON k.src = u.src
WHERE k.rel = 'SUPPLIES_OEM' AND k.dst = 'Kia' AND u.rel = 'HOLDS_STANDARD' AND u.dst = 'UL Certification'
ORDER BY c.company;

SELECT DISTINCT c.company FROM graph_edges k JOIN certifications i ON k.src = i.row_id
WHERE k.rel = 'SUPPLIES_OEM' AND k.dst = 'Porsche Cars North America Inc.' AND i.standard_family = 'IATF 16949'
ORDER BY c.company;
